Problem:
A university has 1200 units of antibiotics to make two creams, a anti-inflammatory cream and a pain-killing cream. A container of anti-inflammatory cream requires 2 units of antibiotics and 4 units of water. A container of pain-killing cream requires 3 units of antibiotics and 2 units of water. The lab has to make at least 50 anti-inflammatory creams. However, since pain-killing creams are in high demand, at least 55% of the total number of creams must be pain-killing creams. How many of each should be made to minimize the total amount of water needed?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "anti-inflammatory cream containers",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "pain-killing cream containers",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "anti-inflammatory cream containers",
     "coef": 4.0
    },
    {
     "var": "pain-killing cream containers",
     "coef": 2.0
    }
   ]
  },
  "constraints": [
   {
    "name": "antibiotics",
    "terms": [
     {
      "var": "anti-inflammatory cream containers",
      "coef": 2.0
     },
     {
      "var": "pain-killing cream containers",
      "coef": 3.0
     }
    ],
    "sense": "<=",
    "rhs": 1200.0
   },
   {
    "name": "min anti-inflammatory",
    "terms": [
     {
      "var": "anti-inflammatory cream containers",
      "coef": 1.0
     }
    ],
    "sense": ">=",
    "rhs": 50.0
   },
   {
    "name": "pain-killing share",
    "terms": [
     {
      "var": "anti-inflammatory cream containers",
      "coef": 0.55
     },
     {
      "var": "pain-killing cream containers",
      "coef": -0.45
     }
    ],
    "sense": "<=",
    "rhs": 0.0
   }
  ]
 },
 "facts": {
  "objective": 324.0,
  "values": {
   "anti-inflammatory cream containers": 50.0,
   "pain-killing cream containers": 62.0
  },
  "binding": [
   "min anti-inflammatory"
  ],
  "slack": {
   "antibiotics": 914.0,
   "min anti-inflammatory": 0.0,
   "pain-killing share": 0.4
  },
  "shadow_prices": null
 }
}
